    return (
        isinstance(s, str)
        and len(s.strip()) >= _SUBQUESTION_MIN_LEN
        and bool(_SUBQUESTION_CHARS.search(s))
    )


class ResearchAgent:
    """Prompt-based deep research agent.

    Subtask 3: adds the evidence acquisition loop (per-subquestion web search +
    page-level browsing) with URL deduplication and time-budget enforcement.
    Final synthesis remains a placeholder.
    """

    def __init__(
        self,
        research_client: Any,
        browsing_client: Any,
        search_engine_tool: Any,
        browsing_agent: Any,
        max_research_time_s: int = 600,
        must_use_search: bool = True,
        top_k_per_subquestion: int = 3,
    ):
        # Injected dependencies; construction does no network or filesystem I/O.
        self.research_client = research_client
        self.browsing_client = browsing_client
        self.search_engine_tool = search_engine_tool
        self.browsing_agent = browsing_agent
        self.max_research_time_s = max_research_time_s
        self.must_use_search = must_use_search
        self.top_k_per_subquestion = top_k_per_subquestion
        self.system_prompt_research_core = SYSTEM_PROMPT_RESEARCH_CORE
        self.system_prompt_browsing_delegate = SYSTEM_PROMPT_BROWSING_DELEGATE

    # ------------------------------------------------------------------ planning

    def _plan_research(self, question: str, metadata: Optional[dict] = None) -> dict:
        """Ask the GPT-4.1 backbone for a strict-JSON research plan."""
        messages = [
            {"role": "system", "content": SYSTEM_PROMPT_RESEARCH_CORE},
            {"role": "user", "content": question},
        ]
        response = self.research_client.get_chat_completion_sync(
            messages=messages, temperature=0.0, max_tokens=1500
        )
        raw = response.choices[0].message.content
        return self._normalize_plan(self._parse_plan_json(raw), question)

    def _parse_plan_json(self, raw: Any) -> dict:
        text = (raw or "").strip()
        if text.startswith("```"):
            text = text[3:]
            if text[:4].lower() == "json":
                text = text[4:]
            if text.endswith("```"):
                text = text[:-3]
            text = text.strip()
        try:
            plan = json.loads(text)
        except (ValueError, TypeError) as exc:
            raise ResearchPlanningError(
                "planner did not return valid JSON"
            ) from exc
        if not isinstance(plan, dict):
            raise ResearchPlanningError("planner JSON must be an object")
        return plan

    def _normalize_plan(self, plan: dict, question: str) -> dict:
        language = plan.get("target_language")
        if language not in ("en", "zh"):
            language = detect_language(question)
        plan["target_language"] = language

        subquestions = [s for s in plan.get("subquestions", []) if _is_quality_subquestion(s)]

        expected = plan.get("expected_answer_type") or "long_explanation"
        must_search = (
            bool(plan.get("must_search", True))
            or bool(self.must_use_search)
            or expected in FACT_ANSWER_TYPES
        )
        if must_search and not any(
            tok in s.lower() for s in subquestions for tok in SEARCH_TOKENS
        ):
            subquestions.append(f"Search the web for: {question}")
        if not subquestions:
            subquestions = [f"Search the web for: {question}"]

        plan["subquestions"] = subquestions
        plan["expected_answer_type"] = expected
        plan["must_search"] = must_search
        return plan

    # ----------------------------------------------------------- evidence loop

    def _gather_evidence(self, plan: dict, steps: Optional[list] = None) -> dict:
        """Search + browse each subquestion, returning a deduplicated evidence set."""
        steps = steps if steps is not None else []
        plan = plan or {}
        evidence = {
            "items": [],
            "truncated": False,
            "search_available": callable(getattr(self.search_engine_tool, "search", None)),
            "search_calls": 0,
            "browse_calls": 0,
            "queries": [],
        }
        if not evidence["search_available"]:
            return evidence

        language = plan.get("target_language") or "en"
        subquestions = plan.get("subquestions") or []
        start = time.time()
        by_url: dict = {}
        order: list = []

        def expired() -> bool:
            return (time.time() - start) > self.max_research_time_s

        for subquestion in subquestions:
            if expired():
                evidence["truncated"] = True
                break

            query = str(subquestion).strip()
            evidence["queries"].append(query)
            steps.append({"t": time.time(), "action": "search", "detail": query})
            try:
                results = self._call(self.search_engine_tool.search, query) or []
            except Exception:
                results = []
            if not results:
                continue
            evidence["search_calls"] += 1

            for result in list(results)[: self.top_k_per_subquestion]:
                if not isinstance(result, dict) or not result.get("url"):
                    continue
                if expired():
                    evidence["truncated"] = True
                    break
                url = result["url"]
                steps.append({"t": time.time(), "action": "browse", "detail": url})
                snippets = self._browse_snippets(url, query, language)
                evidence["browse_calls"] += 1
                if not snippets and str(result.get("snippet", "")).strip():
                    snippets = [result["snippet"]]

                if url in by_url:
                    item = by_url[url]
                    item["snippets"].extend(s for s in snippets if s not in item["snippets"])
                    if subquestion not in item["supporting_subquestions"]:
                        item["supporting_subquestions"].append(subquestion)
                else:
                    by_url[url] = {
                        "url": url,
                        "title": result.get("title", ""),
                        "language": language,
                        "snippets": snippets,
                        "supporting_subquestions": [subquestion],
                    }
                    order.append(url)

            if evidence["truncated"]:
                break

        evidence["items"] = [by_url[u] for u in order]
        return evidence

    def _browse_snippets(self, url: str, query: str, language: str) -> list:
        try:
            browsed = self._browse(url, query, language)
        except Exception:
            return []
        return self._as_snippets(browsed)

    def _browse(self, url: str, query: str, language: str) -> Any:
        browse = getattr(self.browsing_agent, "browse", None)
        if callable(browse):
            return self._call(browse, url, query, language)
        run = getattr(self.browsing_agent, "run", None)
        if callable(run):
            return self._call(run, [{"url": url, "query": query}], query)
        return None

    def _as_snippets(self, value: Any) -> list:
        if isinstance(value, dict):
            value = list(value.values())
        if isinstance(value, (list, tuple)):
            snippets: list = []
            for item in value:
                snippets.extend(self._as_snippets(item))
            return snippets
        if isinstance(value, str) and value.strip():
            return [value]
        return []

    @staticmethod
    def _call(fn, *args, **kwargs) -> Any:
        result = fn(*args, **kwargs)
        if inspect.isawaitable(result):
            # ponytail: drives the async SearchEngineTool/WebBrowsingAgent from a
            # sync run(); a live event loop would need run_coroutine_threadsafe.
            result = asyncio.run(result)
        return result

    # -------------------------------------------------------------------- entry

    def run(self, question: str, metadata: Optional[dict] = None) -> dict:
        metadata = metadata or {}
        steps: list = []
        try:
            plan = self._plan_research(question, metadata)
        except Exception as exc:  # fail gracefully; keep run() total
            plan = {
                "target_language": detect_language(question),
                "subquestions": [],
                "expected_answer_type": "long_explanation",
                "must_search": bool(self.must_use_search),
                "notes": f"planning failed: {exc}",
            }
        steps.append({"t": time.time(), "action": "plan", "detail": question})

        evidence = self._gather_evidence(plan, steps)

        if (
            plan.get("must_search")
            and evidence.get("search_available")
            and evidence.get("search_calls", 0) == 0
        ):
            answer = RETRIEVAL_FAILURE_ANSWER
        else:
            # ponytail: placeholder answer; final synthesis lands in a later subtask.
            answer = PLACEHOLDER_ANSWER

        return {
            "answer": answer,
            "language": plan["target_language"],
            "trace": {
                "models": {
                    "research": getattr(self.research_client, "model_name", RESEARCH_MODEL),
                    "browsing": getattr(self.browsing_client, "model_name", BROWSING_MODEL),
                },
                "tools": {
                    "search_engine_tool": type(self.search_engine_tool).__name__,
                    "browsing_agent": type(self.browsing_agent).__name__,
                },
                "max_research_time_s": self.max_research_time_s,
                "must_use_search": self.must_use_search,
                "metadata": metadata,
                "plan": plan,
                "evidence": evidence,
                "steps": steps,
            },
        }

