@staticmethod
def _evidence_items(evidence: Any) -> list:
    if isinstance(evidence, dict):
        return list(evidence.get("items") or [])
    return list(evidence or [])

def _evidence_ids(self, evidence: Any) -> list:
    return [f"[S{i}]" for i, _ in enumerate(self._evidence_items(evidence), start=1)]

def _build_evidence_context(self, id_map: dict) -> str:
    lines = []
    for sid, item in id_map.items():
        snippets = " | ".join(
            str(s).strip() for s in item.get("snippets", []) if str(s).strip()
        )
        lines.append(
            f"{sid} (title: {item.get('title', '')}; url: {item.get('url', '')}; "
            f"lang: {item.get('language', '')}): {snippets}"
        )
    return "\n".join(lines)

@staticmethod
def _sanitize_citations(text: str, valid_ids: set) -> str:
    return _CITATION_RE.sub(lambda m: m.group(0) if m.group(0) in valid_ids else "", text or "")

@staticmethod
def _extract_citations(text: str, valid_ids: set) -> list:
    used: list = []
    for match in _CITATION_RE.findall(text or ""):
        if match in valid_ids and match not in used:
            used.append(match)
    return used

