    user_payload = (
        f"Question:\n{question}\n\n"
        f"Research plan (JSON):\n{json.dumps(plan_summary, ensure_ascii=False)}\n\n"
        f"Evidence items (cite these exact identifiers):\n"
        f"{self._build_evidence_context(id_map)}\n\n"
        f"Write the final answer in target_language = {language!r}. Annotate every "
        f"verifiable factual claim with the matching evidence identifiers, e.g. [S1], "
